// Source:        NDR / Alerts (ndr.alerts)
// ASIM schema:   Alert Event
// Deploy alias:  vimAlertEventOpenSystemsNdrAlerts
// Owner:         ndr team
// Aggregated by: ../../../../shared/parsers/vimAlertEventOpenSystems.kql
//
// NDR emits a lightweight "alerts" stream (distributor job ndr.alerts), separate from the
// richer CSE stream (job ndr/ndr-eventprocessor). A record is produced when an NDR event
// crossed an elevated threatscore threshold. Both streams carry the same product
// discriminator ResourceAttributes['osag.product.name'] == "ndr"; the alerts stream is
// additionally tagged by the distributor with ResourceAttributes['osag.stream'] == "alerts"
// (set in the chart's transform/ndr_alerts processor), which is the sub-discriminator used
// below so alert records do not collide with the CSE Network Session parser.
//
// These are security alerts, so they normalize onto the ASIM Alert Event schema
// (https://learn.microsoft.com/azure/sentinel/normalization-schema-alert).
//
// Sample raw Body (JSON string):
//   {"ip_namespace":"e2e","ip":"10.0.0.181","firing":true,
//    "timestamp_epoch_ms":1784796117343.0,"date":"2026-07-23T08:41:57Z"}
//
// Ingestion model (ADR-0002, native OTLP): logs land in the single OTelLogs table; the raw
// JSON is the Body column, ingested as a string (parse with todynamic(Body) before dotted
// access). The single `ip` field (the host that crossed the threatscore) maps to DvcIpAddr;
// firing / ip_namespace / timestamp_epoch_ms are carried in AdditionalFields.
// Dynamic fields are accessed with bracket notation (Body['date']) because `date` is a
// reserved KQL keyword that cannot be used with dotted access.
let parser = (
    starttime: datetime = datetime(null),
    endtime: datetime = datetime(null),
    disabled: bool = false
) {
    OTelLogs
    | where not(disabled)
    | where tostring(ResourceAttributes['osag.product.name']) == "ndr"
    | where tostring(ResourceAttributes['osag.stream']) == "alerts"
    | where (isnull(starttime) or TimeGenerated >= starttime)
    | where (isnull(endtime) or TimeGenerated <= endtime)
    // Body is ingested as a JSON string; parse it before dotted field access.
    | extend Body = todynamic(Body)
    | project
        TimeGenerated = todatetime(Body['date']),
        EventStartTime = todatetime(Body['date']),
        EventEndTime = todatetime(Body['date']),
        EventCount = int(1),
        EventType = "Alert",
        EventSubType = "Threat",
        EventOriginalType = "ndr.alerts",
        EventVendor = "Open Systems",
        EventProduct = "NDR",
        EventSchema = "AlertEvent",
        EventSchemaVersion = "0.1",
        EventSeverity = "Medium",
        AlertName = "NDR threat score threshold exceeded",
        EventMessage = strcat("NDR alert firing for host ", tostring(Body['ip'])),
        DetectionMethod = "Network Detection and Response",
        ThreatCategory = "Unknown",
        DvcIpAddr = tostring(Body['ip']),
        AdditionalFields = bag_pack(
            "firing", tostring(Body['firing']),
            "ip_namespace", tostring(Body['ip_namespace']),
            "timestamp_epoch_ms", tostring(Body['timestamp_epoch_ms']))
};
parser(starttime, endtime, disabled)

// Source:        ZTNA / identity-aware connector (IDAC) audit log
// ASIM schema:   Audit Event
// Deploy alias:  vimAuditEventOpenSystemsZtna
// Owner:         ztna team
// Aggregated by: ../../../../shared/parsers/vimAuditEventOpenSystems.kql
//
// Per-source ("source-specific") ASIM parser. Member of the unifying Open Systems
// Audit Event parser. Keep the filtering parameter signature so the unifying parser can
// push filters down for performance.
//
// ZTNA audit records are admin configuration-change events: a subject (admin user)
// performs an action (create/update/delete) on a configured authority (the managed
// object) with a success/failure result. These normalize onto the ASIM Audit Event
// schema (https://learn.microsoft.com/azure/sentinel/normalization-schema-audit).
//
// Ingestion model (ADR-0002, native OTLP): logs land in the single OTelLogs table; the
// raw ZTNA record is the Body column, ingested as a string (parse with todynamic(Body)
// before dotted access); the discriminator is ResourceAttributes['osag.product.name']
// == "ztna". IDAC emits several message types under one product, so the "audit" stream is
// selected via Body.message_type.
//
// ASIM naming note: upstream ASIM names the unifier `_Im_AuditEvent` and per-source
// parsers `imAuditEvent<Vendor>`. Open Systems keeps the repo `vim<schema>OpenSystems`
// convention (matches every other source here); confirm the final FunctionAlias with OSAP
// before the customer-side savedSearches deploy.
let parser = (
    starttime: datetime = datetime(null),
    endtime: datetime = datetime(null),
    disabled: bool = false
) {
    OTelLogs
    | where not(disabled)
    // Discriminate on the resource attribute set by the OTel distributor.
    | where tostring(ResourceAttributes['osag.product.name']) == "ztna"
    // Body is ingested as a JSON string; parse it before dotted field access.
    | extend Body = todynamic(Body)
    // IDAC emits several message types; select the admin-config "audit" stream.
    | where tostring(Body.message_type) == "audit"
    | where (isnull(starttime) or TimeGenerated >= starttime)
    | where (isnull(endtime) or TimeGenerated <= endtime)
    // Map raw Body fields onto the ASIM Audit Event schema (see schema.json).
    | project
        // ZTNA audit records carry a payload timestamp, but for consistency with the
        // activity parser and the OTLP MV we use the OTLP record time for all three.
        TimeGenerated,
        EventStartTime = TimeGenerated,
        EventEndTime = TimeGenerated,
        EventCount = int(1),
        EventVendor = "Open Systems",
        EventProduct = "ZTNA",
        EventSchema = "AuditEvent",
        EventSchemaVersion = "0.1.2",
        Dvc = "ZTNA",
        EventUid = tostring(Body.uuid),
        EventType = case(
            tostring(Body.action) == "create", "Create",
            tostring(Body.action) == "update", "Set",
            tostring(Body.action) == "delete", "Delete",
            "Other"),
        Operation = tostring(Body.action),
        EventResult = case(
            tostring(Body.result) == "success", "Success",
            "Failure"),
        EventResultDetails = tostring(Body.result),
        Object = tostring(Body.authority_name),
        ObjectType = "Configuration Atom",
        ObjectId = tostring(Body.object_name),
        ActorUsername = tostring(Body.subject_name),
        ActorUsernameType = "UPN",
        TargetDomain = tostring(Body.ztna_tenant)
};
parser(starttime, endtime, disabled)

// Source:        Open Systems Auth / Zitadel identity provider login events
// ASIM schema:   Authentication
// Deploy alias:  vimAuthenticationOpenSystemsAuth
// Owner:         OSAP
// Aggregated by: ../../../shared/parsers/vimAuthenticationOpenSystems.kql
//
// Per-source ("source-specific") ASIM parser. It is a member of the unifying
// Open Systems Authentication parser. Keep the filtering parameter signature so the
// unifying parser can push filters down for performance.
//
// Auth records are Zitadel login-attempt notifications: the distributor's
// transform/auth_attribute + transform/auth processors (charts/logs-api/templates/
// _helpers.tpl) already select only "authentication"-typed Zitadel log lines, unwrap
// the nested JSON payload, and keep exactly {login, remoteAddress, result, time,
// error} as Body (companyId is promoted to the resource attribute company_id for
// customer routing and is intentionally not exported to Sentinel). These normalize
// onto the ASIM Authentication schema
// (https://learn.microsoft.com/azure/sentinel/normalization-schema-authentication).
let parser = (
    starttime: datetime = datetime(null),
    endtime: datetime = datetime(null),
    disabled: bool = false
) {
    OTelLogs
    | where not(disabled)
    // Discriminate on the resource attribute set by the OTel distributor.
    | where tostring(ResourceAttributes['osag.product.name']) == "auth"
    // Body is ingested as a JSON string; parse it before dotted field access.
    | extend Body = todynamic(Body)
    | where (isnull(starttime) or TimeGenerated >= starttime)
    | where (isnull(endtime) or TimeGenerated <= endtime)
    | project
        TimeGenerated = todatetime(Body["time"]),
        EventStartTime = todatetime(Body["time"]),
        EventEndTime = todatetime(Body["time"]),
        EventCount = int(1),
        EventType = "Logon",
        EventResult = case(
            tostring(Body.result) has_cs "successful", "Success",
            tostring(Body.result) has_cs "failure", "Failure",
            "NA"),
        EventResultDetails = tostring(Body.error),
        EventVendor = "Open Systems",
        EventProduct = "Auth",
        EventSchema = "Authentication",
        EventSchemaVersion = "0.1.4",
        Dvc = "Auth",
        TargetUsername = tostring(Body.login),
        TargetUsernameType = "UPN",
        SrcIpAddr = tostring(Body.remoteAddress[0])
};
parser(starttime, endtime, disabled)

// Source:        MEP (Mobile Entry Point) / Cisco ASA VPN login (syslog)
// ASIM schema:   Authentication
// Deploy alias:  vimAuthenticationOpenSystemsMep
// Owner:         mep team
// Aggregated by: ../../../shared/parsers/vimAuthenticationOpenSystems.kql
//
// Per-source ("source-specific") ASIM parser. It is a member of the unifying
// Open Systems Authentication parser. Keep the filtering parameter signature so the
// unifying parser can push filters down for performance.
//
// MEP login records are VPN session assignments emitted by Cisco ASA: when a user
// authenticates, the ASA assigns a session and logs the group, user, client IP and
// assigned VPN IP. These normalize onto the ASIM Authentication schema
// (https://learn.microsoft.com/azure/sentinel/normalization-schema-authentication).
//
// Ingestion model (ADR-0002, native OTLP): logs land in the single OTelLogs table;
// the raw ASA record is the Body column, ingested as a STRING. Unlike the JSON sources,
// ASA logs are free-form syslog text, so fields are pulled with extract() regexes
// (the same patterns mv_otlp_logs_to ... logins uses) rather than todynamic(Body).
// The discriminator is ResourceAttributes['osag.product.name'] == "mep". Only the
// "assigned to session" line carries a successful login, so it is selected as the
// "logins" stream.
//
// Field source-of-truth: the logins columns in
// platforms/data-mesh/clickhouse/config/atlas/schemas/mep/logins.ch.hcl
// (logins_local_mv_tmp extracts the raw ASA fields onto those columns via the same
// regexes used below).
//
// Deliberately unmapped (no clean ASIM Authentication home):
//   group        - VPN tunnel-group assignment
//   assigned_ip  - the internal VPN address allocated to the client
let parser = (
    starttime: datetime = datetime(null),
    endtime: datetime = datetime(null),
    disabled: bool = false
) {
    OTelLogs
    | where not(disabled)
    // Discriminate on the resource attribute set by the OTel distributor.
    | where tostring(ResourceAttributes['osag.product.name']) == "mep"
    // ASA emits many syslog lines; select the successful session-assignment login line.
    | where Body has "assigned to session"
    | where (isnull(starttime) or TimeGenerated >= starttime)
    | where (isnull(endtime) or TimeGenerated <= endtime)
    // Body is free-form ASA syslog text; pull fields with the same regexes as the MV.
    | project
        // ASA lines carry no separate payload timestamp; the event time is the OTLP
        // record time (logins_local_mv_tmp uses the same LogRecord Timestamp).
        TimeGenerated,
        EventVendor = "Open Systems",
        EventProduct = "MEP",
        EventSchema = "Authentication",
        EventSchemaVersion = "0.1.4",
        EventType = "Logon",
        // Only successful session assignments reach this parser.
        EventResult = "Success",
        Dvc = "MEP",
        TargetUsername = extract(@"User <([^>]+)>", 1, tostring(Body)),
        TargetUsernameType = "Simple",
        SrcIpAddr = extract(@"IP <([^>]+)>", 1, tostring(Body))
};
parser(starttime, endtime, disabled)

// Source:        ZTNA / identity-aware connector (IDAC) activity log
// ASIM schema:   Authentication
// Deploy alias:  vimAuthenticationOpenSystemsZtna
// Owner:         ztna team
// Aggregated by: ../../../../shared/parsers/vimAuthenticationOpenSystems.kql
//
// Per-source ("source-specific") ASIM parser. It is a member of the unifying
// Open Systems Authentication parser. Keep the filtering parameter signature so the
// unifying parser can push filters down for performance.
//
// ZTNA activity records represent the full user activity stream: application-access
// decisions — a subject (user) is allowed/denied access to a ZTNA-protected object
// (application) via the IDAC, carrying an access_allowed/access_denied status — and
// generic user activity (e.g. agent downloads) that carries no status. All are
// subject->target access events and normalize onto the ASIM Authentication schema
// (https://learn.microsoft.com/azure/sentinel/normalization-schema-authentication).
// The access/activity kind is classified into EventSubType.
//
// Ingestion model (ADR-0002, native OTLP): logs land in the single OTelLogs table;
// the raw ZTNA record is the Body column, ingested as a string (parse with
// todynamic(Body) before dotted access); the discriminator is ResourceAttributes
// ['osag.product.name'] == "ztna". IDAC emits several message types under one product,
// so the "activity" stream is selected via Body.message_type.
//
// Field source-of-truth: the activity_logs columns in
// platforms/data-mesh/clickhouse/config/atlas/schemas/ztna/ztna_activity_logs.ch.hcl
// (mv_otlp_logs_to_ztna_activity_logs_local maps the raw log fields onto those columns).
let parser = (
    starttime: datetime = datetime(null),
    endtime: datetime = datetime(null),
    disabled: bool = false
) {
    OTelLogs
    | where not(disabled)
    // Discriminate on the resource attribute set by the OTel distributor.
    | where tostring(ResourceAttributes['osag.product.name']) == "ztna"
    // Body is ingested as a JSON string; parse it before dotted field access.
    | extend Body = todynamic(Body)
    // IDAC emits several message types; select the user-access "activity" stream.
    | where tostring(Body.message_type) == "activity"
    | where (isnull(starttime) or TimeGenerated >= starttime)
    | where (isnull(endtime) or TimeGenerated <= endtime)
    // Map raw Body fields onto the ASIM Authentication schema (see schema.json).
    // Access decisions carry a status; generic activity (e.g. agent downloads) does not.
    | extend ActivityStatus = tostring(Body.status)
    | project
        // ZTNA records carry no payload timestamp; the event time is the OTLP
        // record time (mv_otlp_logs_to_ztna_activity_logs uses the same LogRecord Timestamp).
        TimeGenerated,
        EventVendor = "Open Systems",
        EventProduct = "ZTNA",
        EventSchema = "Authentication",
        EventSchemaVersion = "0.1.4",
        // ASIM Authentication EventType enum is Logon/Logoff/Elevate; ZTNA activity is
        // fundamentally an access/logon. Finer classification lives in EventSubType.
        EventType = "Logon",
        EventSubType = iff(isnotempty(ActivityStatus), "ApplicationAccess", "Activity"),
        EventResult = case(
            ActivityStatus == "access_allowed", "Success",
            ActivityStatus == "access_denied", "Failure",
            "NA"),
        EventResultDetails = ActivityStatus,
        EventMessage = tostring(Body.message),
        EventUid = tostring(Body.uuid),
        Dvc = "ZTNA",
        TargetUsername = tostring(Body.subject_name),
        TargetUsernameType = "UPN",
        TargetAppName = tostring(Body.object_name_portal),
        TargetAppId = tostring(Body.object_name),
        TargetAppType = "Resource",
        TargetDomain = tostring(Body.ztna_tenant),
        SrcIpAddr = tostring(Body.remote_address)
};
parser(starttime, endtime, disabled)

// Source:        Netcore / DHCP server (CPE DHCP lease events)
// ASIM schema:   DhcpEvent
// Deploy alias:  vimDhcpEventOpenSystemsDhcp
// Owner:         netcore team
// Aggregated by: ../../../shared/parsers/vimDhcpEventOpenSystems.kql
//
// Per-source ("source-specific") ASIM parser for the netcore/CPE DHCP server stream.
// The CPE runs a DHCP server that emits one lease-operation record per client request;
// it is onboarded as its own product under the netcore service family (the same way
// ndr/zeek is a distinct product from ndr/ndr under one service family).
//
// Ingestion model (ADR-0002, native OTLP): logs land in the single OTelLogs table; the
// raw DHCP record is the Body column, ingested as a string (parse with todynamic(Body)
// before dotted access); the discriminator is
// ResourceAttributes['osag.product.name'] == "dhcp". The distributor must tag the DHCP
// job with this product name in the collector pipeline (charts/logs-api
// templates/_helpers.tpl). That routing does not exist yet, so this parser returns no
// rows until it is added.
//
// EventType mapping: ASIM DhcpEvent only allows Assign / Renew / Release / DNS Update,
// so the raw DHCP operation (DHCPDISCOVER/OFFER/REQUEST/ACK/NAK/DECLINE/RELEASE/INFORM)
// is collapsed onto those values and the original is preserved in EventOriginalType.
// ASIM DhcpEvent reference:
// https://learn.microsoft.com/azure/sentinel/normalization-schema-dhcp
let parser = (
    starttime: datetime = datetime(null),
    endtime: datetime = datetime(null),
    disabled: bool = false
) {
    OTelLogs
    | where not(disabled)
    | where tostring(ResourceAttributes['osag.product.name']) == "dhcp"
    | where (isnull(starttime) or TimeGenerated >= starttime)
    | where (isnull(endtime) or TimeGenerated <= endtime)
    // Body is ingested as a JSON string; parse it before dotted field access.
    | extend Body = todynamic(Body)
    | extend
        EventTime = unixtime_milliseconds_todatetime(tolong(Body.timestamp)),
        Operation = toupper(tostring(Body.operation))
    | project
        TimeGenerated = EventTime,
        EventStartTime = EventTime,
        EventEndTime = EventTime,
        EventCount = int(1),
        EventType = case(
            Operation == "DHCPRELEASE", "Release",
            Operation == "DHCPINFORM", "Renew",
            "Assign"),
        EventResult = iff(Operation in ("DHCPNAK", "DHCPDECLINE"), "Failure", "Success"),
        EventOriginalType = tostring(Body.operation),
        EventVendor = "Open Systems",
        EventProduct = "DHCP",
        EventSchema = "DhcpEvent",
        EventSchemaVersion = "0.1.1",
        Dvc = tostring(Body.host_id),
        DvcId = tostring(Body.host_id),
        DvcIdType = "Other",
        DvcIpAddr = tostring(Body.server_ip),
        SrcIpAddr = tostring(Body.host_ip),
        // ASIM: when no client hostname is available, store the client IP in SrcHostname.
        SrcHostname = iff(isempty(tostring(Body.host_name)), tostring(Body.host_ip), tostring(Body.host_name)),
        SrcMacAddr = tostring(Body.host_mac)
};
parser(starttime, endtime, disabled)

// Source:        Firewall / DNS inspection daemon (dns.inspection.sentinel.avro topic)
// ASIM schema:   Dns
// Deploy alias:  vimDnsOpenSystemsDnsInspection
// Owner:         firewall team
// Aggregated by: ../../../shared/parsers/vimDnsOpenSystems.kql
//
// Per-source ("source-specific") ASIM parser for the firewall DNS-inspection stream.
// DNS inspection is a firewall feature, but it ships a payload unrelated to the fwlog
// connection log, so it is onboarded as its own product with its own strictly-typed
// parser (the same way ndr/zeek is a distinct product from ndr/ndr under one service
// family). The firewall NetworkSession parser is left untouched.
//
// Ingestion model (ADR-0002, native OTLP): logs land in the single OTelLogs table;
// the raw DNS-inspection record is the Body column, ingested as a string (parse with
// todynamic(Body) before dotted access); the discriminator is ResourceAttributes
// ['osag.product.name'] == "dns-inspection". The distributor must tag the DNS-inspection
// job (Kafka topic dns.inspection.sentinel.avro.v1.6) with this product name in the
// collector pipeline (charts/logs-api templates/_helpers.tpl). That routing does not
// exist yet, so this parser returns no rows until it is added.
//
// The firewall emits the DNS response code and query type as numbers; the IANA lookup
// tables below resolve them to names, mirroring the legacy parser documented in
// docs/deprecated/vimDnsOpenSystemsDnsInspection.md.
// Enum reference: https://www.iana.org/assignments/dns-parameters/dns-parameters.xhtml
let RCodeName = datatable(flags_rc: long, ResponseCodeName: string) [
    0, "NOERROR", 1, "FORMERR", 2, "SERVFAIL", 3, "NXDOMAIN", 4, "NOTIMP",
    5, "REFUSED", 6, "YXDOMAIN", 7, "YXRRSET", 8, "NXRRSET", 9, "NOTAUTH",
    10, "NOTZONE", 11, "DSOTYPENI", 16, "BADVERS", 17, "BADKEY", 18, "BADTIME",
    19, "BADMODE", 20, "BADNAME", 21, "BADALG", 22, "BADTRUNC", 23, "BADCOOKIE"
];
let RCodeResult = datatable(flags_rc: long, ResponseCodeResult: string) [
    0, "Success", 1, "Failure", 2, "Failure", 3, "Success", 4, "Failure",
    5, "Failure", 6, "Partial", 7, "Partial", 8, "Partial", 9, "Failure",
    10, "Failure", 11, "Failure", 16, "Failure", 17, "Failure", 18, "Failure",
    19, "Failure", 20, "Failure", 21, "Failure", 22, "Failure", 23, "Failure"
];
let RRTypeName = datatable(query_qtype: long, QueryTypeName: string) [
    0, "Reserved", 1, "A", 2, "NS", 3, "MD", 4, "MF", 5, "CNAME", 6, "SOA",
    7, "MB", 8, "MG", 9, "MR", 10, "NULL", 11, "WKS", 12, "PTR", 13, "HINFO",
    14, "MINFO", 15, "MX", 16, "TXT", 17, "RP", 18, "AFSDB", 19, "X25", 20, "ISDN",
    21, "RT", 22, "NSAP", 23, "NSAP-PTR", 24, "SIG", 25, "KEY", 26, "PX", 27, "GPOS",
    28, "AAAA", 29, "LOC", 30, "NXT", 31, "EID", 32, "NIMLOC", 33, "SRV", 34, "ATMA",
    35, "NAPTR", 36, "KX", 37, "CERT", 38, "A6", 39, "DNAME", 40, "SINK", 41, "OPT",
    42, "APL", 43, "DS", 44, "SSHFP", 45, "IPSECKEY", 46, "RRSIG", 47, "NSEC",
    48, "DNSKEY", 49, "DHCID", 50, "NSEC3", 51, "NSEC3PARAM", 52, "TLSA", 53, "SMIMEA",
    55, "HIP", 56, "NINFO", 57, "RKEY", 58, "TALINK", 59, "CDS", 60, "CDNSKEY",
    61, "OPENPGPKEY", 62, "CSYNC", 63, "ZONEMD", 64, "SVCB", 65, "HTTPS", 99, "SPF",
    100, "UINFO", 101, "UID", 102, "GID", 103, "UNSPEC", 104, "NID", 105, "L32",
    106, "L64", 107, "LP", 108, "EUI48", 109, "EUI64", 249, "TKEY", 250, "TSIG",
    251, "IXFR", 252, "AXFR", 253, "MAILB", 254, "MAILA", 255, "*", 256, "URI",
    257, "CAA", 258, "AVC", 259, "DOA", 260, "AMTRELAY", 32768, "TA", 32769, "DLV",
    65535, "Reserved"
];
let parser = (
    starttime: datetime = datetime(null),
    endtime: datetime = datetime(null),
    disabled: bool = false
) {
    OTelLogs
    | where not(disabled)
    | where tostring(ResourceAttributes['osag.product.name']) == "dns-inspection"
    | where (isnull(starttime) or TimeGenerated >= starttime)
    | where (isnull(endtime) or TimeGenerated <= endtime)
    // Body is ingested as a JSON string; parse it before dotted field access.
    | extend Body = todynamic(Body)
    // Payload event time (epoch milliseconds) and the numeric DNS enums.
    | extend
        EventTime = unixtime_milliseconds_todatetime(tolong(Body.timestamp)),
        EventSubType = iff(toupper(tostring(Body["flags"]["qr"])) == "RESPONSE", "response", "request"),
        flags_rc = tolong(Body["flags"]["rc"]),
        query_qtype = tolong(Body["query"]["qtype"])
    // Resolve the numeric enums to their IANA names.
    | lookup kind=leftouter RCodeName on flags_rc
    | lookup kind=leftouter RCodeResult on flags_rc
    | lookup kind=leftouter RRTypeName on query_qtype
    | project
        TimeGenerated = EventTime,
        EventStartTime = EventTime,
        EventEndTime = EventTime,
        EventCount = int(1),
        EventType = "Query",
        EventSubType,
        EventResult = case(
            tobool(Body.block), "Failure",
            EventSubType != "response", "NA",
            isnotempty(ResponseCodeResult), ResponseCodeResult,
            "Success"),
        EventResultDetails = coalesce(ResponseCodeName, "Unassigned"),
        EventVendor = "Open Systems",
        EventProduct = "DNS Inspection",
        EventSchema = "Dns",
        EventSchemaVersion = "0.1.7",
        Dvc = "DNS Inspection",
        NetworkProtocol = toupper(tostring(Body.protocol)),
        SrcIpAddr = tostring(Body.originator_ip),
        SrcPortNumber = toint(Body.originator_port),
        DstIpAddr = tostring(Body.responder_ip),
        DstPortNumber = toint(Body.responder_port),
        DnsQuery = trim_end(@"\.", tostring(Body["query"]["name"])),
        DnsQueryType = toint(query_qtype),
        DnsQueryTypeName = coalesce(QueryTypeName, "Unassigned"),
        DnsResponseCode = toint(flags_rc),
        DnsResponseCodeName = coalesce(ResponseCodeName, "Unassigned"),
        DnsResponseName = iff(EventSubType == "response", tostring(Body.answers), "")
};
parser(starttime, endtime, disabled)

// Source:        NDR / Zeek dns.log
// ASIM schema:   Dns
// Deploy alias:  vimDnsOpenSystemsZeek
// Owner:         ndr team
// Aggregated by: ../../../../shared/parsers/vimDnsOpenSystems.kql
//
// Per-source ("source-specific") ASIM parser for the Zeek dns.log stream. One product
// (Zeek) fans out into several ASIM schemas: conn -> NetworkSession, dns -> Dns,
// http -> WebSession. Each stream is its own folder with its own schema.json + parser.
//
// Ingestion model (ADR-0002, native OTLP): all logs land in the single OTelLogs
// table. The raw Zeek record is the Body column, ingested as a string (parse with
// todynamic(Body) before field access); the product discriminator is the
